contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        // Seed the test contract as recipient by calling getFirstWithdrawalBonus,
        // which credits 100 wei to the test contract and then withdraws it.
        bool seedReverted;
        c.getFirstWithdrawalBonus(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            seedReverted = true;
        } else {
            seedReverted = false;
        }

        // If seeding succeeded, the contract's balance decreased by 100 wei after paying us.
        // Then a direct withdrawReward for the same recipient should now have no reward
        // and must not revert (recipient is this contract, which accepts Ether).
        bool withdrawReverted;
        uint balBefore = address(c).balance;
        c.withdrawReward(address(this)); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        assert(seedReverted || !withdrawReverted);
    }
}

