// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        bool seedReverted;
        try c.getFirstWithdrawalBonus(address(this)) {
            seedReverted = false;
        } catch {
            seedReverted = true;
        }
        bool withdrawReverted;
        uint balBefore = address(c).balance;
        try c.withdrawReward(address(this)) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        assertTrue(seedReverted || !withdrawReverted);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
